using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioDialogueBatchOperations:RefCounted
{
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var v)?v:fallback;
    private static double N(Settings d,string key,double fallback=0)=>Get(d,key,fallback).AsDouble();
    private static double N(GodotObject o,string key)=>o.Get(key).AsDouble();
    private static string S(Settings d,string key,string fallback="")=>Get(d,key,fallback).AsString();
    private static GArray Items(GodotObject o,string key)=>o.Get(key).AsGodotArray();
    private static Settings Failure(string error)=>new(){["error"]=error};
    public Settings analyze(RefCounted document,GArray ids,double threshold,double minimum,RefCounted? job)
    {
        if(ids.Count==0||ids.Count>64)return Failure("Select between 1 and 64 dialogue clips.");var entries=new GArray();using var edits=new AudioEditSessionOperations();using var regions=new AudioRegionEditOperations();using var analysis=new AudioAnalysisOperations();foreach(var id in ids){if(job!=null&&job.Call("is_cancelled").AsBool())return Failure("Cancelled.");var clip=document.Call("clip_for_id",id.AsString()).AsGodotObject();var actor=document.Call("actor_for_clip",id.AsString()).AsGodotObject();if(clip==null||actor==null)return Failure("A selected clip is unavailable.");string reason=regions.unsupported_reason(clip,actor,"cut");if(reason.Length>0)return Failure(actor.Get("display_name").AsString()+": "+reason);string identity=edits.silence_source_identity(actor);var data=analysis.analyze_source(Get(actor.Get("values").AsGodotDictionary(),"audio"),threshold,minimum,job,N(clip,"source_offset"),N(clip,"duration")*N(clip,"playback_speed"));if(S(data,"error").Length>0)return data;if(identity.Length==0||identity!=edits.silence_source_identity(actor))return Failure("A dialogue source changed during analysis.");entries.Add(new Settings{["id"]=id.AsString(),["label"]=actor.Get("display_name"),["data"]=data,["identity"]=identity});job?.Call("update",(double)entries.Count/ids.Count,"Reviewing dialogue sources");}return new Settings{["error"]="",["entries"]=entries};
    }
    public Settings prepare(RefCounted session,GArray entries,double keep)
    {
        var plans=new GArray();using var edits=new AudioEditSessionOperations();foreach(var raw in entries){var entry=raw.AsGodotDictionary();var data=entry["data"].AsGodotDictionary();var result=edits.create_silence_plan(session,S(entry,"id"),Get(data,"silences",new GArray()).AsGodotArray(),N(data,"duration"),keep,S(entry,"identity"));if(S(result,"error").Length>0)return result;plans.Add(result["plan"]);}return new Settings{["error"]="",["plans"]=plans};
    }
    public Settings review(RefCounted session,GArray plans,GArray choices,string scope,double overlap)
    {
        if(plans.Count!=choices.Count||plans.Count==0||plans.Count>64)return Failure("Invalid dialogue review queue.");if(!double.IsFinite(overlap)||overlap<0||overlap>.1)return Failure("Choose a crossfade between 0 and 100 ms.");var operations=new GArray();var seen=new System.Collections.Generic.HashSet<string>();double total=0;var document=session.Get("document").AsGodotObject();using var edits=new AudioEditSessionOperations();using var regions=new AudioRegionEditOperations();
        for(int index=0;index<plans.Count;index++)
        {
            var plan=plans[index].AsGodotObject() as RefCounted;if(plan==null)return Failure("Duplicate or missing dialogue plan.");string id=plan.Call("clip_id").AsString();if(!seen.Add(id))return Failure("Duplicate or missing dialogue plan.");var preview=edits.preview_silence_plan(session,plan,choices[index].AsGodotArray(),scope);if(S(preview,"error").Length>0)return preview;var clip=document.Call("clip_for_id",id).As<Resource>();var actor=document.Call("actor_for_clip",id).AsGodotObject();var values=actor.Get("values").AsGodotDictionary();string fade=S(values,"fade_curve","linear");if(overlap>0&&fade is not ("linear" or "")&&(N(values,"fade_in")>0||N(values,"fade_out")>0))return Failure("Render existing nonlinear outer fades first, or set overlap to zero. Their curve will not be silently changed.");var ranges=preview["ranges"].AsGodotArray();var parts=new GArray();double cursor=N(clip,"start_time"),speed=N(clip,"playback_speed");var joins=new System.Collections.Generic.List<double>();
            for(int i=0;i<ranges.Count-1;i++){var left=ranges[i].AsGodotDictionary();var right=ranges[i+1].AsGodotDictionary();joins.Add(Math.Min(overlap*.5,Math.Min((N(right,"start")-N(left,"end"))/speed*.5,Math.Min(N(left,"end")-N(left,"start"),N(right,"end")-N(right,"start"))/speed*.25)));}
            for(int i=0;i<ranges.Count;i++){var interval=ranges[i].AsGodotDictionary();double head=i>0?joins[i-1]:0,tail=i<joins.Count?joins[i]:0,length=(N(interval,"end")-N(interval,"start"))/speed;var part=regions.piece(actor,clip,cursor-head,N(interval,"start")-head*speed,length+head+tail);var partActor=part["actor"].AsGodotObject();var partClip=part["clip"].AsGodotObject();if(i==0){partActor.Set("id",actor.Get("id"));partClip.Set("id",clip.Get("id"));partClip.Set("actor_id",actor.Get("id"));}var partValues=partActor.Get("values").AsGodotDictionary();partValues[new StringName("fade_in")]=head>0?head*2:i==0?N(values,"fade_in"):Math.Min(.003,length*.1);partValues[new StringName("fade_out")]=tail>0?tail*2:i==ranges.Count-1?N(values,"fade_out"):Math.Min(.005,length*.1);if(head>0||tail>0)partValues[new StringName("fade_curve")]="linear";parts.Add(part);cursor+=length;}
            operations.Add(new Settings{["id"]=clip.Get("id"),["track"]=Get(values,"track_id",""),["end"]=N(clip,"start_time")+N(clip,"duration"),["removed"]=N(preview,"removed"),["parts"]=parts,["moved"]=preview["moved_ids"]});total+=N(preview,"removed");
        }
        return new Settings{["error"]="",["operations"]=operations,["removed"]=total,["scope"]=scope};
    }
    public Settings apply(RefCounted session,GArray plans,GArray choices,string scope,double overlap)
    {
        var result=review(session,plans,choices,scope,overlap);if(S(result,"error").Length>0||N(result,"removed")<=.000001)return result;var shifts=new Settings();var operations=result["operations"].AsGodotArray();if(scope=="track_following")foreach(var raw in operations){var operation=raw.AsGodotDictionary();foreach(var id in operation["moved"].AsGodotArray())shifts[id]=Get(shifts,id.AsString(),0).AsDouble()+N(operation,"removed");}foreach(var raw in plans)raw.AsGodotObject().Call("cancel");session.Call("action","Reviewed dialogue queue",Callable.From(()=>{var document=session.Get("document").AsGodotObject();var clips=Items(document,"clips");var actors=Items(document,"actors");foreach(var raw in operations){var operation=raw.AsGodotDictionary();if(N(operation,"removed")<=.000001)continue;var clip=document.Call("clip_for_id",operation["id"]).AsGodotObject();int index=clips.IndexOf(clip);clips.RemoveAt(index);actors.RemoveAt(index);var parts=operation["parts"].AsGodotArray();for(int i=0;i<parts.Count;i++){var part=parts[i].AsGodotDictionary();var partClip=part["clip"].AsGodotObject();partClip.Set("start_time",N(partClip,"start_time")-Get(shifts,S(operation,"id"),0).AsDouble());clips.Insert(index+i,partClip);actors.Insert(index+i,part["actor"]);}shifts.Remove(operation["id"]);}foreach(var id in shifts.Keys){var clip=document.Call("clip_for_id",id).AsGodotObject();if(clip!=null)clip.Set("start_time",N(clip,"start_time")-shifts[id].AsDouble());}var selected=Items(session,"selected_ids");selected.Clear();foreach(var raw in operations)foreach(var partRaw in raw.AsGodotDictionary()["parts"].AsGodotArray()){var clip=partRaw.AsGodotDictionary()["clip"].AsGodotObject();if(document.Call("clip_for_id",clip.Get("id")).AsGodotObject()!=null)selected.Add(clip.Get("id"));}}));session.EmitSignal("selection_changed");return new Settings{["error"]="",["removed"]=result["removed"]};
    }
}
